/** Skip `range.start` bytes and emit the rest of the range, releasing the source once done. */
function sliceStream(
  stream: ReadableStream<Uint8Array>,
  range: ByteRange,
): ReadableStream<Uint8Array> {
  const reader = stream.getReader();
  let skip = range.start;
  let remaining = range.end - range.start + 1;
  return new ReadableStream<Uint8Array>({
    async pull(controller) {
      while (true) {
        const { done, value } = await reader.read();
        if (done) {
          controller.close();
          return;
        }
        let chunk = value;
        if (skip > 0) {
          const dropped = Math.min(skip, chunk.byteLength);
          skip -= dropped;
          chunk = chunk.subarray(dropped);
        }
        if (chunk.byteLength > 0) {
          const emit = chunk.subarray(0, remaining);
          remaining -= emit.byteLength;
          controller.enqueue(emit);
          if (remaining === 0) {
            await reader.cancel();
            controller.close();
          }
          return;
        }
      }
    },
    cancel(reason) {
      return reader.cancel(reason);
    },
  });
}

